<?php
declare(strict_types=1);if(PHP_SAPI!=='cli'){http_response_code(404);exit;}$configPath=__DIR__.'/config.php';if(!is_file($configPath)){fwrite(STDERR,"config missing\n");exit(2);}$config=require$configPath;$days=(int)($config['retention_days']??0);if($days<1||$days>3650){fwrite(STDERR,"invalid retention_days\n");exit(2);}try{$pdo=new PDO((string)$config['db']['dsn'],(string)$config['db']['user'],(string)$config['db']['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);$cutoff=(new DateTimeImmutable('now',new DateTimeZone('UTC')))->modify('-'.$days.' days')->format('Y-m-d H:i:s');$ids=$pdo->prepare('SELECT id FROM tp_integrated_sessions WHERE received_at < ? ORDER BY id LIMIT 500');$ids->execute([$cutoff]);$list=array_map('intval',array_column($ids->fetchAll(),'id'));$deleted=0;foreach($list as$id){$pdo->beginTransaction();$pdo->prepare('DELETE FROM tp_integrated_reflections WHERE session_id=?')->execute([$id]);$pdo->prepare('DELETE e FROM tp_integrated_pair_events e JOIN tp_integrated_blocks b ON b.id=e.block_id WHERE b.session_id=?')->execute([$id]);$pdo->prepare('DELETE a FROM tp_integrated_attempts a JOIN tp_integrated_blocks b ON b.id=a.block_id WHERE b.session_id=?')->execute([$id]);$pdo->prepare('DELETE FROM tp_integrated_blocks WHERE session_id=?')->execute([$id]);$d=$pdo->prepare('DELETE FROM tp_integrated_sessions WHERE id=?');$d->execute([$id]);$deleted+=$d->rowCount();$pdo->commit();}echo "retention_cleanup deleted_sessions=$deleted\n";}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();fwrite(STDERR,"retention cleanup failed\n");error_log('2Pair retention cleanup: '.$e->getMessage());exit(1);}
